import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';
import {nativeSQL} from './snapshot/src/native/store.ts';
import {syntheticSource,prepareSyntheticV2Upgrade,applySyntheticV2Upgrade} from './snapshot/scripts/v2-upgrade-offline.mjs';
const enabled={execute:true,syntheticFixture:true};
globalThis.fetch=async()=>{throw Error('OUTBOUND_FORBIDDEN');};
function seed(db){db.exec("UPDATE cla_native_v2_state SET revision=17; INSERT INTO cla_native_v2_sessions(rowid,token_hash,actor,login,csrf_hash,expires) VALUES(9007199254740993,'SYNTHETIC',2,CAST(X'80FF' AS TEXT),X'0080FF',123)");}
function fresh(){const db=new DatabaseSync(':memory:');for(const f of ['base.sql','native/schema.sql'])db.exec(nativeSQL(fs.readFileSync(new URL('./snapshot/src/'+f,import.meta.url),'utf8')));return db;}
function snapshot(db){const s=db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE sql IS NOT NULL ORDER BY type,name").all();const q=db.prepare('SELECT rowid,token_hash,actor,hex(login) login,hex(csrf_hash) csrf,expires FROM cla_native_v2_sessions');q.setReadBigInts(true);return {schema:s,rows:q.all(),revision:db.prepare('SELECT revision FROM cla_native_v2_state').get().revision};}
test('source plan cannot claim preservation on an independently created fresh target',()=>{
 const source=syntheticSource(),target=fresh();try{
  seed(source);seed(target);const plan=prepareSyntheticV2Upgrade(source),targetPlan=prepareSyntheticV2Upgrade(target),before=snapshot(target);
  assert.equal(plan.status,'prepared');assert.equal(targetPlan.status,'already_target');assert.equal(targetPlan.schema_sha256,plan.fresh_target_schema_sha256);assert.notEqual(targetPlan.schema_sha256,plan.target_schema_sha256);
  const exec=target.exec.bind(target),executed=[];target.exec=sql=>{executed.push(sql);return exec(sql);};
  let result,error;try{result=applySyntheticV2Upgrade(target,plan,enabled);}catch(e){error=e;}finally{target.exec=exec;}
  console.log(JSON.stringify({fresh_schema:targetPlan.schema_sha256,actual_alter_schema:plan.target_schema_sha256,result,error:error?.message}));
  assert.deepEqual(snapshot(target),before);assert.equal(target.isTransaction,false);
  assert.ok(error,'an independent fresh target must reject the source plan instead of claiming already_applied/data_preserved');
  assert.match(error.message,/prepared_plan_changed|upgrade_provenance|source_plan|schema/);assert.deepEqual(executed,['BEGIN IMMEDIATE','ROLLBACK']);
 }finally{source.close();target.close();}
});
test('a fresh target accepts its own exact no-op plan',()=>{
 const target=fresh();try{seed(target);const plan=prepareSyntheticV2Upgrade(target),before=snapshot(target),exec=target.exec.bind(target),executed=[];target.exec=sql=>{executed.push(sql);return exec(sql);};let result;
  try{result=applySyntheticV2Upgrade(target,plan,enabled);}finally{target.exec=exec;}assert.deepEqual(executed,['BEGIN IMMEDIATE','COMMIT']);
  assert.equal(result.status,'already_target');assert.equal(result.writes,0);assert.deepEqual(snapshot(target),before);assert.equal(target.isTransaction,false);
 }finally{target.close();}
});
test('an actual ALTER-upgraded source still recognizes its own exact original plan',()=>{
 const source=syntheticSource();try{seed(source);const plan=prepareSyntheticV2Upgrade(source);assert.equal(applySyntheticV2Upgrade(source,plan,enabled).status,'upgraded_synthetic_only');
  const targetPlan=prepareSyntheticV2Upgrade(source);assert.equal(targetPlan.schema_sha256,plan.target_schema_sha256);const before=snapshot(source),exec=source.exec.bind(source),executed=[];source.exec=sql=>{executed.push(sql);return exec(sql);};let result;
  try{result=applySyntheticV2Upgrade(source,plan,enabled);}finally{source.exec=exec;}assert.deepEqual(executed,['BEGIN IMMEDIATE','COMMIT']);
  assert.equal(result.status,'already_applied');assert.equal(result.data_preserved,true);assert.deepEqual(snapshot(source),before);assert.equal(source.isTransaction,false);
 }finally{source.close();}
});
